/**
 * The things that move on a planet's area, as its host tells them in the
 * planet's room (cube-sphere/1, Things that move): each drawn as its box
 * under the area about the visitor, at its place in the area's block
 * coordinates and turned as the format says (by its pitch about its own x
 * axis, then by its yaw about +y; a positive yaw turns +z toward −x, a
 * positive pitch +z toward +y).
 *
 * Each message is the area's whole list: a thing it leaves out is removed,
 * and one it names moves from where it is drawn to its new place over the
 * time since the last message, so it glides a message behind rather than
 * jumping. A message no later than the last taken is stale. An area that
 * has been silent for SILENT_MS has its things cleared, as are an area's
 * things when the visitor leaves it.
 *
 * Whether they are drawn, their colour and whether they glide are the
 * world's, under the visitor's choice of whether they are drawn (`look`,
 * thingsLook.ts); the shell's own where neither says.
 */
import type { Scene } from '@babylonjs/core/scene';
import { Color3 } from '@babylonjs/core/Maths/math.color';
import type { Mesh } from '@babylonjs/core/Meshes/mesh';
import type { TransformNode } from '@babylonjs/core/Meshes/transformNode';
import { GetClass } from '@babylonjs/core/Misc/typeStore';
import type { StandardMaterial } from '../../engine/shaderImports';
import type { ThingsLook } from './thingsLook';

export type { ThingsLook } from './thingsLook';

/** How long an area may be silent before its things are taken away, in milliseconds: cube-sphere/1's 5 seconds. */
const SILENT_MS = 5000;
/** The time a thing takes to reach a newly told place: the time since the message before, within these bounds. */
const GLIDE_MS = { least: 50, most: 1000 };
/** The shell's colour for a thing drawn as its box, where the world gives none. */
const THING_COLOUR: [number, number, number] = [0.55, 0.6, 0.68];
const SHELL_LOOK: ThingsLook = { shown: true, colour: null, glide: true };

type Vec3 = [number, number, number];
interface Pose {
  pos: Vec3;
  yaw: number;
  pitch: number;
}
interface Thing {
  node: TransformNode;
  from: Pose;
  to: Pose;
  start: number;
  glide: number;
}

export interface MovingThings {
  /** A message from the planet's room: true where it is an area's things (taken, or ignored as stale or elsewhere). */
  told(path: string, intent: unknown): boolean;
  /** Each frame: the things placed for now, and an area left or silent cleared. */
  tick(): void;
  dispose(): void;
  /** The things drawn now, by id: for tests. */
  drawn(): ReadonlyMap<string, TransformNode>;
}

const PATH = /^planet\/area\/([a-z0-9-]+)\/objects$/;
const finite = (v: unknown): v is number => typeof v === 'number' && Number.isFinite(v);
const triple = (v: unknown): v is Vec3 => Array.isArray(v) && v.length === 3 && v.every(finite);
const six = (v: unknown): v is [number, number, number, number, number, number] => Array.isArray(v) && v.length === 6 && v.every(finite);

/** The shortest way round from one angle to another, in radians. */
const turnBetween = (a: number, b: number) => {
  const d = (((b - a) % (2 * Math.PI)) + 3 * Math.PI) % (2 * Math.PI) - Math.PI;
  return d;
};

export function createMovingThings(o: { scene: Scene; area(): { node: TransformNode; region: string } | null; now?: () => number; look?: () => ThingsLook }): MovingThings {
  const now = o.now ?? (() => performance.now());
  const lookNow = o.look ?? (() => SHELL_LOOK);
  const things = new Map<string, Thing>();
  let region: string | null = null;
  let parent: TransformNode | null = null;
  let lastAt = -Infinity;
  let heardAt = -Infinity;
  let look: StandardMaterial | undefined;

  // The classes the scene already has, so this chunk loads no material, mesh or shader code of its own (the
  // published-world boot shares them, and a second copy would split them out of it).
  const Lit = o.scene.defaultMaterial.constructor as typeof StandardMaterial;
  const Meshes = GetClass('BABYLON.Mesh') as (typeof Mesh & { CreateBox(name: string, size: number, scene: Scene): Mesh }) | null;
  const lookOf = () => {
    if (!look) {
      look = new Lit('planet-thing', o.scene);
      look.specularColor = new Color3(0, 0, 0);
    }
    const c = lookNow().colour ?? THING_COLOUR;
    look.diffuseColor.set(c[0], c[1], c[2]);
    return look;
  };
  const remove = (id: string) => {
    things.get(id)?.node.dispose(false, false);
    things.delete(id);
  };
  const clear = () => {
    for (const id of [...things.keys()]) remove(id);
    region = null;
    parent = null;
    lastAt = -Infinity;
  };
  const place = (t: Thing, p: Pose) => {
    t.node.position.set(p.pos[0], p.pos[1], p.pos[2]);
    // Babylon turns by its own sense: about y, +z toward +x; about x, +z toward −y. Pitch first, then yaw, as the format.
    t.node.rotation.set(-p.pitch, -p.yaw, 0);
  };
  const poseNow = (t: Thing, at: number): Pose => {
    const k = t.glide <= 0 ? 1 : Math.min(1, Math.max(0, (at - t.start) / t.glide));
    const lerp = (a: number, b: number) => a + (b - a) * k;
    return {
      pos: [lerp(t.from.pos[0], t.to.pos[0]), lerp(t.from.pos[1], t.to.pos[1]), lerp(t.from.pos[2], t.to.pos[2])],
      yaw: t.from.yaw + turnBetween(t.from.yaw, t.to.yaw) * k,
      pitch: lerp(t.from.pitch, t.to.pitch),
    };
  };

  return {
    told(path, intent) {
      const m = PATH.exec(path);
      if (!m) return false;
      const area = o.area();
      const body = intent as { at?: unknown; objects?: unknown } | null;
      if (!area || area.region !== m[1] || !body || !finite(body.at) || !Array.isArray(body.objects) || !lookNow().shown) return true;
      if (region !== area.region || parent !== area.node) {
        clear();
        region = area.region;
        parent = area.node;
      }
      if (body.at <= lastAt) return true;
      lastAt = body.at;
      const t = now();
      const glide = Math.min(GLIDE_MS.most, Math.max(GLIDE_MS.least, t - heardAt));
      heardAt = t;
      const told = new Set<string>();
      for (const x of body.objects) {
        const thing = x as Record<string, unknown> | null;
        if (!thing || typeof thing['id'] !== 'string' || !thing['id'] || !triple(thing['pos'])) continue;
        const id = thing['id'];
        const to: Pose = { pos: [...thing['pos']] as Vec3, yaw: finite(thing['yaw']) ? thing['yaw'] : 0, pitch: finite(thing['pitch']) ? thing['pitch'] : 0 };
        told.add(id);
        const had = things.get(id);
        if (had) {
          had.from = poseNow(had, t);
          had.to = to;
          had.start = t;
          had.glide = lookNow().glide ? glide : 0;
          continue;
        }
        if (!Meshes?.CreateBox) continue;
        // An empty mesh as the thing's own frame: it draws nothing itself.
        const node = new Meshes(`planet-thing-${id}`, o.scene);
        node.parent = area.node;
        const b: [number, number, number, number, number, number] = six(thing['box']) ? thing['box'] : [-0.5, -0.5, -0.5, 0.5, 0.5, 0.5];
        const box = Meshes.CreateBox(`planet-thing-box-${id}`, 1, o.scene);
        box.parent = node;
        box.scaling.set(b[3] - b[0], b[4] - b[1], b[5] - b[2]);
        box.position.set((b[0] + b[3]) / 2, (b[1] + b[4]) / 2, (b[2] + b[5]) / 2);
        box.material = lookOf();
        box.isPickable = false;
        const fresh: Thing = { node, from: to, to, start: t, glide: 0 };
        place(fresh, to);
        things.set(id, fresh);
      }
      for (const id of [...things.keys()]) if (!told.has(id)) remove(id);
      return true;
    },

    tick() {
      const area = o.area();
      const t = now();
      if (things.size === 0) return;
      if (!area || area.region !== region || area.node !== parent || t - heardAt > SILENT_MS || !lookNow().shown) {
        clear();
        return;
      }
      // The world's colour, read live: a script may change it.
      lookOf();
      for (const thing of things.values()) place(thing, poseNow(thing, t));
    },

    dispose() {
      clear();
      look?.dispose();
      look = undefined;
    },

    drawn: () => new Map([...things].map(([id, t]) => [id, t.node])),
  };
}
