/**
 * Which block a visitor points at, in an area's blocks: a block spans its
 * node position ± 0.5, as Luanti's does. The ray is walked block by block
 * (Amanatides and Woo), so it costs a few steps however far it reaches.
 *
 * Where the ray crosses an edge or a corner exactly, every block it only
 * touches there is passed over (it has no length inside them), and the face
 * entered is the one across the up-down axis first, then x, then z.
 */

export type Vec3 = [number, number, number];

export interface Picked {
  /** The block pointed at. */
  block: Vec3;
  /** The face entered, as its outward normal. */
  face: Vec3;
  /** Where a placed block goes: beside that face. */
  place: Vec3;
  /** A liquid's top block, pointed at where nothing solid is within reach under it: placed into, never dug. */
  liquid?: boolean;
}

export interface PickWorld {
  /** Whether a pointer stops at the block. */
  solid(x: number, y: number, z: number): boolean;
  /** Whether the block is known yet; a pick stops, with nothing, at one that is not. */
  known?(x: number, y: number, z: number): boolean;
  /** Told of each block the ray passes through within reach before the one it stops at, in order, with the face it entered by. */
  passed?(x: number, y: number, z: number, face: Vec3): void;
}

/** Equal crossings within this, in metres along the ray, are one crossing: an edge or a corner. */
const TIE = 1e-9;
/** Which axis's face is named where several are entered at once: y, then x, then z. */
const PRIORITY = [1, 0, 2] as const;

export function pickBlock(world: PickWorld, eye: Vec3, dir: Vec3, reach: number): Picked | null {
  const len = Math.hypot(dir[0], dir[1], dir[2]);
  if (!(len > 0) || !(reach > 0)) return null;
  const d = [dir[0] / len, dir[1] / len, dir[2] / len];
  const cell = [Math.floor(eye[0] + 0.5), Math.floor(eye[1] + 0.5), Math.floor(eye[2] + 0.5)];
  const step = d.map((v) => Math.sign(v));
  const next = [0, 1, 2].map((k) => (d[k] === 0 ? Infinity : (cell[k]! + 0.5 * step[k]! - eye[k]!) / d[k]!));
  const delta = d.map((v) => (v === 0 ? Infinity : 1 / Math.abs(v)));
  // A ray never leaves more than this many blocks within reach.
  for (let i = 0; i < 3 * Math.ceil(reach + 2); i++) {
    const t = Math.min(next[0]!, next[1]!, next[2]!);
    if (t > reach) return null;
    let axis = -1;
    for (const k of PRIORITY) {
      if (next[k]! - t > TIE) continue;
      cell[k]! += step[k]!;
      next[k]! += delta[k]!;
      if (axis < 0) axis = k;
    }
    const [x, y, z] = cell as Vec3;
    if (world.known && !world.known(x, y, z)) return null;
    const face: Vec3 = [0, 0, 0];
    face[axis] = -step[axis]!;
    if (world.solid(x, y, z)) return { block: [x, y, z], face, place: [x + face[0], y + face[1], z + face[2]] };
    world.passed?.(x, y, z, face);
  }
  return null;
}
